import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第98章 取消","description":"","frontmatter":{},"headers":[],"relativePath":"第98章_取消.md","filePath":"第98章_取消.md"}'),_={name:"第98章_取消.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第98章-取消" tabindex="-1">第98章 取消 <a class="header-anchor" href="#第98章-取消" aria-label="Permalink to &quot;第98章 取消&quot;">​</a></h1><p>后天早上六点，她发了一句取消。</p><p>她说，我今天来不了。</p><p>我说，怎么了。</p><p>她说，我妈今天早上血压高。</p><p>她说，我要带她去一个医院。</p><p>她说，我九点的号。</p><p>我说，那你去看。</p><p>她说，我跟你说一声，你在里面别等。</p><p>我说，我不等。</p><p>她说，你今天就一个人坐在那儿。</p><p>我说，我一个人坐过四年。</p><p>她说，你别讲这句。</p><p>我说，我讲实话。</p><p>她说，你讲这句我今天就难受。</p><p>她说，我本来就在难受。</p><p>她说，我今天早上五点半她叫我，她说话含含糊糊，我站在那里我没动。</p><p>她说，我怕我一开口我就哭。</p><p>她说，我这一辈子我妈生病我一次也没哭过。</p><p>她说，因为我哭了我妈就要起来安慰我。</p><p>她说，我不许她起来。</p><p>我说，你现在在哪儿。</p><p>她说，我在医院门口。</p><p>她说，我还没挂号。</p><p>她说，我在那个大厅外面那个台阶上坐着。</p><p>我说，那你去。</p><p>她说，我今天不能去那个机场。</p><p>我说，我知道。</p><p>她说，你不要跟我说&quot;没事&quot;。</p><p>我说，我不说没事。</p><p>她说，那你说什么。</p><p>我说，我说你今天先带你妈把号挂上。</p><p>她说，好。</p><p>我说，我这边你不用管。</p><p>她说，我知道你不用我管。</p><p>她说，你这个人在机场里坐着你能坐一整天。</p><p>她说，我给你点一个东西到你那个登机口。</p><p>我说，不行，我那边你送不到。</p><p>她说，我这边能。</p><p>她说，我这个软件能送到你们那个机场里面。</p><p>我说，你别花。</p><p>她说，四十。</p><p>她说，我今天在花四十块钱让我自己不要想那个台阶。</p><p>我说，那你要什么。</p><p>她说，一杯咖啡，一个面包。</p><p>她说，你不要讲&quot;你别花钱&quot;。</p><p>她说，我今天要是连四十块都不敢花，我今天一天我就完了。</p><p>我说，那你买。</p><p>她说，我买了。</p><p>她说，我送到你那个 B 口。</p><p>她说，你二十分钟以后下去拿。</p><p>我说，我在 B 口。</p><p>她说，我知道你在 B 口。</p><p>她说，我给你发了一条，你说你到了，你坐在那个第三排椅子上。</p><p>我说，你怎么知道是第三排。</p><p>她说，因为你去年给我发过一张你在机场的照片，你那个椅子扶手上有胶带，我看到过那个胶带。</p><p>她说，我们那个机场也有这一种椅子。</p><p>我说，我这把没有胶带。</p><p>她说，那你在第三排，因为第一排和第二排是宽的。</p><p>我说，你今天在干什么。</p><p>她说，我挂完号了，我在她们那个走廊上坐着。</p><p>她说，我妈在里面量血压。</p><p>她说，我今天没有带本子。</p><p>她说，我今天坐在这儿，我不能画，我不能给你讲话，我就只能看你那边。</p><p>她说，你那边几点。</p><p>我说，我这里九点四十。</p><p>她说，我这里十点四十。</p><p>她说，我们两个现在只隔一个钟头。</p><p>我说，我知道。</p><p>她说，你别算这个。</p><p>她说，我今天算了一早上。</p><p>她说，我算出来我这一辈子跟你的时间从来没有近过像今天这样。</p><p>她说，然后我今天来不了。</p><p>我说，你先量完血压。</p><p>她说，闻迟。</p><p>她说，你今年讲话很像我妈。</p><p>我说，哪里像。</p><p>她说，就是不管发生什么，你先让人把那个事办完。</p><p>她说，你今天要是跟我说一句&quot;你不用来&quot;，我就真的不用来。</p><p>她说，你要是说一句&quot;我在这儿等&quot;，我今天就要从我妈那个走廊上跑出去。</p><p>我说，我不讲这两句。</p><p>她说，那你讲什么。</p><p>我说，我说你把血压量完。</p><p>她说，好。</p><p>她说，我量完我给你发。</p><p>那杯咖啡和那个面包在十点十七到了。</p><p>我下去拿的时候，那个取餐台上贴着一张单子。</p><p>单子上写着：不要冰。</p><p>那是她每次给我点东西都会加的那一句。</p><p>我站在那里看着那五个字。</p><p>我看着那张纸，心里想的是另一件事。</p><p>我想：她今天早上五点五十坐在医院门口那个台阶上，她手上有汗，她把&quot;不要冰&quot;三个字打得很准。</p><p>她那天没有来。</p><p>我们那天隔着一个城市、一个半钟头、一张取餐单。</p><p>我登机前给她发了一句。</p><p>我说，我吃完了。</p><p>她说，咖啡好喝吗。</p><p>我说，太苦。</p><p>她说，那你别喝。</p><p>我说，我喝完了。</p><p>她说，我知道你会喝完。</p><p>她说，你这个人你不浪费别人给你的东西。</p><p>我说，你今天怎么样了。</p><p>她说，她血压降下来了。</p><p>她说，她现在在睡觉。</p><p>她说，我在她病床边上坐着。</p><p>她说，我今天一天哪儿也没去。</p><p>我说，那挺好。</p><p>她说，你别&quot;那挺好&quot;。</p><p>她说，我今天在一张椅子上坐了一天，我坐的这把椅子扶手上有胶带。</p><p>我说，你那边也有第三排？</p><p>她说，我们这里第三排是坏的。</p><p>她说，我坐在那个坏的上面，我一直不敢往后靠。</p><p>下午一点那个保温杯的人又回来了。</p><p>他坐到我旁边。</p><p>他把那个杯盖拧开，吹了一下。</p><p>他说，等人？</p><p>我说，等完了。</p><p>他说，那你不走。</p><p>我说，我改签了。</p><p>他说，你改到几点。</p><p>我说，晚上七点。</p><p>他说，为什么。</p><p>我说，我今天那四小时用不完。</p><p>他没说话。</p><p>他过了一会儿说了一句。</p><p>他说，你这个人在这里坐了一上午。</p><p>他说，你等的那个人没来。</p><p>他说，你不恨她。</p><p>我说，我不恨。</p><p>他说，那你为什么改到七点。</p><p>我说，因为我现在出去也没地方去。</p><p>他说，你可以回去。</p><p>我说，回去我要讲今天。</p><p>他说，讲今天怎么了。</p><p>我说，我今天讲不出来。</p><p>那个人把杯盖拧回去。</p><p>他说，你们这些小孩。</p><p>他说，你们什么都拿一张嘴接着。</p><p>他说，你明天就能讲了。</p><p>他说，人讲话这个东西，是要隔一夜的。</p><p>他说，你今天不讲不是因为你不想讲。</p><p>他说，是因为你今天还没有想好你在讲给谁。</p><p>我那天下午在那个 B 口坐到六点五十。</p><p>我把那个咖啡喝了，把面包吃了，把那个纸袋叠了一下，叠成一个很小的方块。</p><p>我把它放进了兵袋最外面那一格。</p><p>我那天晚上七点上的飞机。</p><p>我九点落地。</p><p>我到家以后洗了脸，坐在床上，屏幕上跳进来一张图。</p><p>是她。</p><p>那是她们医院那一排椅子。</p><p>不锈钢的，扶手那里缠了一圈白胶带，胶带已经脏成灰色。</p><p>她说，就是这个。</p><p>她说，我坐了一天这个。</p><p>她说，你说的那个第三排，我今天数了。</p><p>她说，我们这里从门口数第三排，就是扶手坏的那一排。</p><p>她说，我坐在那个坏的上面坐了一天，我不敢往后靠。</p><p>她说，我今天忽然发现一件事。</p><p>我说，什么。</p><p>她说，我们两个今天坐在同一把椅子上。</p><p>她说，不一样的城市，不一样的人，同一把坏了扶手的椅子。</p><p>我说，嗯。</p><p>她说，你看，你又嗯。</p><p>她说，你今天拿一个嗯，就把我今天一天坐在那把椅子上的事接走了。</p><p>我说，那你要我讲什么。</p><p>她说，你讲一句你今天也在那把椅子上坐了。</p><p>我说，我今天在那个 B 口第三排坐了六个钟头。</p><p>她说，好。</p><p>她说，这下我们两个都坐过了。</p>',169)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
